// ... other functions

int db_add_testimonial(const Testimonial* testimonial) {
    // Assume db_get_conn() returns a valid sqlite3* connection
    sqlite3* db = db_get_conn();
    sqlite3_stmt* stmt;
    const char* sql = "INSERT INTO testimonials (user_id, author_name, comment) VALUES (?, ?, ?);";

    if (sqlite3_prepare_v2(db, sql, -1, &stmt, NULL) != SQLITE_OK) {
        fprintf(stderr, "Failed to prepare statement: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    sqlite3_bind_int(stmt, 1, testimonial->user_id);
    sqlite3_bind_text(stmt, 2, testimonial->author_name, -1, SQLITE_STATIC);
    sqlite3_bind_text(stmt, 3, testimonial->comment, -1, SQLITE_STATIC);

    if (sqlite3_step(stmt) != SQLITE_DONE) {
        fprintf(stderr, "Failed to execute statement: %s\n", sqlite3_errmsg(db));
        sqlite3_finalize(stmt);
        return -1;
    }

    sqlite3_finalize(stmt);
    return 0;
}
```

